div>\r\n                    <div className=\"line-group\">\r\n                        <FormGroup className=\"description-group\">\r\n                            <label className=\"control-label\">{getResource('Description')} (optional)</label>\r\n                            <div className=\"field control-content\">\r\n                                <textarea className={`form-control none-resize ${!isValidDescription && InputErrorCssClass}`}\r\n                                    rows=\"5\" maxLength=\"200\"\r\n                                    name=\"description\" value={values.description}\r\n                                    onChange={this.props.onChange}\r\n                                />\r\n                            </div>\r\n                        </FormGroup>\r\n                    </div>\r\n                </Modal.Body>\r\n                <Modal.Footer>\r\n                    <Button className=\"btn-cancel\" onClick={this.props.onClose}>{getResource('Cancel')}</Button>\r\n                    <Button type=\"submit\" bsStyle=\"primary\">{getResource('Submit')}</Button>\r\n                </Modal.Footer>\r\n            </Form>\r\n        );\r\n    }\r\n}","import React, { Component } from 'react';\r\nimport ReactDOM from 'react-dom';\r\nimport { Tabs, Tab } from 'react-bootstrap';\r\n\r\nimport getResource from '../../resourceHelper';\r\nimport ToastLayout from '../../shared/layouts/ToastLayout';\r\nimport Breadcrumb from '../../shared/components/Breadcrumb';\r\nimport EOQ from './eoq/index';\r\nimport EOY from './eoy/index';\r\n\r\nexport default class App extends Component {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            activeKey: parseInt(document.getElementById('ActiveTab').value, 10),\r\n            isFirstLoad: parseInt(document.getElementById('ActiveTab').value, 10) === 2\r\n        };\r\n    }\r\n\r\n    handleSelect = key => {\r\n        this.setState({ activeKey: key });\r\n\r\n        if (key === 2 && !this.state.isFirstLoad) {\r\n            this.setState({ isFirstLoad: true });\r\n        }\r\n    };\r\n\r\n    render() {\r\n        return (\r\n            <ToastLayout>\r\n                <div className=\"row\">\r\n                    <Breadcrumb>\r\n                        <li className=\"current\">{getResource('NominationPeriod')}</li>\r\n                    </Breadcrumb>\r\n                    <div className=\"col-sm-12\">\r\n                        <Tabs id=\"tabs\"\r\n                            activeKey={this.state.activeKey}\r\n                            onSelect={this.handleSelect}\r\n                        >\r\n\r\n                            <Tab eventKey={1} title={getResource('EmployeeOfTheQuarter')}>\r\n                                <EOQ />\r\n                            </Tab>\r\n                            <Tab eventKey={2} title={getResource('MostOutstandingEmployeeOfTheYear')}>\r\n                                {\r\n                                    this.state.isFirstLoad &&\r\n                                    <EOY />\r\n                                }\r\n                            </Tab>\r\n                        </Tabs>\r\n                    </div>\r\n                </div>\r\n            </ToastLayout>\r\n        );\r\n    }\r\n}\r\n\r\nReactDOM.render(<App />, document.getElementById('nomination-wrapper'));","import React, { Component, Fragment } from 'react';\r\nimport axios from 'axios';\r\n\r\nimport { axiosError, resolveClientUrl } from '../../../common-functions';\r\nimport Filter from './Filter';\r\nimport Table from './Table';\r\n\r\nexport default class EOQ extends Component {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            year: '',\r\n            statusId: 1,\r\n            years: [],\r\n            eoqs: []\r\n        };\r\n\r\n        this.isHost = document.getElementById('IsHost').checked;\r\n    }\r\n\r\n    componentDidMount() {\r\n        this.getYears();\r\n        this.getAllEOQ();\r\n    }\r\n\r\n    getYears = () => {\r\n        axios.get(resolveClientUrl('EOQ/GetYears'))\r\n            .then(response => {\r\n                const data = response.data;\r\n\r\n                this.setState({\r\n                    years: data,\r\n                    year: data[0]\r\n                });\r\n            }).catch(axiosError);\r\n    };\r\n\r\n    getAllEOQ = () => {\r\n        axios.get(resolveClientUrl(`EOQ/GetAll?year=${this.state.year}&statusId=${this.state.statusId}`))\r\n            .then(response => {\r\n                const data = response.data;\r\n\r\n                this.setState({ eoqs: data });\r\n            }).catch(axiosError);\r\n    };\r\n\r\n    handleYearChange = year => {\r\n        this.setState({ year });\r\n    };\r\n\r\n    handleStatusChange = statusId => {\r\n        this.setState({ statusId });\r\n    };\r\n\r\n    handleSubmit = () => {\r\n        this.getAllEOQ();\r\n    };\r\n\r\n    render() {\r\n        return (\r\n            <Fragment>\r\n                <Filter years={this.state.years}\r\n                    year={this.state.year}\r\n                    statusId={this.state.statusId}\r\n                    handleYearChange={this.handleYearChange}\r\n                    handleStatusChange={this.handleStatusChange}\r\n                    handleFilterSubmit={this.handleSubmit}\r\n                />\r\n\r\n                <Table\r\n                    eoqs={this.state.eoqs}\r\n                    isHost={this.isHost}\r\n                    handleFilterSubmit={this.handleSubmit}\r\n                />\r\n            </Fragment>\r\n        );\r\n    }\r\n}","import React, { Component } from 'react';\r\nimport { Form, ControlLabel, FormGroup } from 'react-bootstrap';\r\nimport Select from 'react-select';\r\nimport isEqual from 'react-fast-compare';\r\n\r\nimport { statusOptions } from '../common';\r\nimport getResource from '../../../resourceHelper';\r\n\r\nclass Filter extends Component {\r\n    shouldComponentUpdate(nextProps) {\r\n        return !isEqual(this.props, nextProps);\r\n    }\r\n\r\n    handleYearChange = selectedOption => {\r\n        this.props.handleYearChange(selectedOption.value);\r\n    };\r\n\r\n    handleStatusChange = selectedOption => {\r\n        this.props.handleStatusChange(selectedOption.value);\r\n    };\r\n\r\n    handleSubmit = event => {\r\n        event.preventDefault();\r\n        this.props.handleFilterSubmit();\r\n    };\r\n\r\n    render() {\r\n        const yearOptions = this.props.years.map(year => {\r\n            return { value: year.toString(), label: year };\r\n        });\r\n        yearOptions.unshift({ value: '', label: '-- All --' });\r\n        const yearSelected = yearOptions.find(option => option.value === this.props.year.toString());\r\n\r\n        const statusSelected = statusOptions.find(option => option.value === this.props.statusId.toString());\r\n\r\n        return (\r\n            <Form inline className=\"form-filter\" onSubmit={this.handleSubmit}>\r\n                <FormGroup>\r\n                    <ControlLabel>{getResource('Year')}</ControlLabel>\r\n                    <div className=\"control-content\">\r\n                        <Select name=\"Year\" isSearchable={false} isClearable={false}\r\n                            className=\"react-select-container\" classNamePrefix=\"react-select\"\r\n                            value={yearSelected}\r\n                            options={yearOptions}\r\n                            onChange={this.handleYearChange}\r\n                        />\r\n                    </div>\r\n                </FormGroup>\r\n                <FormGroup>\r\n                    <ControlLabel>{getResource('Status')}</ControlLabel>\r\n                    <div className=\"control-content\">\r\n                        <Select name=\"StatusId\" isSearchable={false} isClearable={false}\r\n                            className=\"react-select-container\" classNamePrefix=\"react-select\"\r\n                            value={statusSelected}\r\n                            options={statusOptions}\r\n                            onChange={this.handleStatusChange}\r\n                        />\r\n                    </div>\r\n                </FormGroup>\r\n                <FormGroup>\r\n                    <button className=\"btn btn-primary\">{getResource('Search')}</button>\r\n                </FormGroup>\r\n            </Form>\r\n        );\r\n    }\r\n}\r\n\r\nexport default Filter;","import React, { Component, Fragment } from 'react';\r\nimport axios from 'axios';\r\nimport { toast } from 'react-toastify';\r\nimport { stringify } from 'qs';\r\n\r\nimport { axiosError, resolveClientUrl } from '../../../common-functions';\r\nimport { PostRequestHeaders } from '../../../constants';\r\nimport getResource from '../../../resourceHelper';\r\nimport ConfirmationModal from '../../../shared/components/ConfirmationModal';\r\nimport Row from './Row';\r\nimport CreateEOQ from './Create';\r\n\r\nclass Table extends Component {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            showCreateModal: false,\r\n            showDeleteModal: false,\r\n            eoqSelected: null\r\n        };\r\n    }\r\n\r\n    handleShowCreateModal = () => this.setState({ showCreateModal: true });\r\n\r\n    handleCloseCreateModal = () => this.setState({ showCreateModal: false });\r\n\r\n    handleShowDeleteModal = eoqSelected => {\r\n        this.setState({\r\n            showDeleteModal: true,\r\n            eoqSelected: eoqSelected\r\n        });\r\n    };\r\n\r\n    handleCloseDeleteModal = () => {\r\n        this.setState({\r\n            showDeleteModal: false,\r\n            eoqSelected: null\r\n        });\r\n    };\r\n\r\n    handleDeleteEOQ = () => {\r\n        axios({\r\n            url: resolveClientUrl('NominationPeriod/Delete'),\r\n            method: 'DELETE',\r\n            data: stringify({\r\n                __RequestVerificationToken: document.getElementsByName('__RequestVerificationToken')[0].value,\r\n                id: this.state.eoqSelected.eoqyId\r\n            }),\r\n            headers: PostRequestHeaders\r\n        }).then(response => {\r\n            const data = response.data;\r\n\r\n            if (data.isSuccessful) {\r\n                toast.success(getResource('DeletedSuccessfully'));\r\n\r\n                this.closeDeleteModal();\r\n                this.props.handleFilterSubmit();\r\n            } else {\r\n                toast.error(data.message);\r\n            }\r\n        }).catch(axiosError);\r\n    };\r\n\r\n    render() {\r\n        const { isHost, eoqs } = this.props;\r\n\r\n        return (\r\n            <Fragment>\r\n                {\r\n                    isHost &&\r\n                    <div className=\"add-nomination-period\">\r\n                        <a className=\"pull-left btn btn-primary\" onClick={this.handleShowCreateModal}>\r\n                            {getResource('AddNominationPeriod')}\r\n                        </a>\r\n                    </div>\r\n                }\r\n                <div className=\"table-nomination-period\">\r\n                    <table className=\"table table-bordered\">\r\n                        <thead>\r\n                            <tr>\r\n                                <th>{getResource('SymbolCount')}</th>\r\n                                <th>{getResource('Quarter')}</th>\r\n                                <th>{getResource('Year')}</th>\r\n                                <th>{getResource('StartDateForNominator')}</th>\r\n                                <th>{getResource('EndDateForNominator')}</th>\r\n                                <th>{getResource('RemindDateForNominator')}</th>\r\n                                <th>{getResource('EndDateForCommittee')}</th>\r\n                                <th>{getResource('Status')}</th>\r\n                                <th>{getResource('Action')}</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            {\r\n                                eoqs.length === 0 &&\r\n                                <tr>\r\n                                    <td className=\"empty-result\" colSpan=\"9\">{getResource('NoRecordFound')}</td>\r\n                                </tr>\r\n                            }\r\n                            {\r\n                                eoqs.length > 0 &&\r\n                                eoqs.map((eoq, index) => {\r\n                                    return (\r\n                                        <Row key={'eoq-' + eoq.eoqyId}\r\n                                            rowIndex={index + 1}\r\n                                            eoq={eoq}\r\n                                            isHost={isHost}\r\n                                            onShowDeleteModal={this.handleShowDeleteModal}\r\n                                        />\r\n                                    );\r\n                                })\r\n                            }\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n                {\r\n                    this.state.showCreateModal &&\r\n                    <CreateEOQ\r\n                        showModal={this.state.showCreateModal}\r\n                        closeModal={this.handleCloseCreateModal}\r\n                        handleFilterSubmit={this.props.handleFilterSubmit}\r\n                    />\r\n                }\r\n                {\r\n                    this.state.showDeleteModal &&\r\n                    <ConfirmationModal\r\n                        action=\"delete\"\r\n                        name={this.state.eoqSelected.title}\r\n                        showModal={this.state.showDeleteModal}\r\n                        onCloseModal={this.handleCloseDeleteModal}\r\n                        onSubmit={this.handleDeleteEOQ}\r\n                    />\r\n                }\r\n            </Fragment>\r\n        );\r\n    }\r\n}\r\n\r\nexport default Table;","import React, { Component, Fragment } from 'react';\r\nimport moment from 'moment';\r\n\r\nimport { resolveClientUrl } from '../../../common-functions';\r\nimport { DateFormat } from '../../../constants';\r\nimport { getCssClassNominationStatus, nominationSettingStatuses } from '../common';\r\n\r\nclass Row extends Component {\r\n    formatDate(value) {\r\n        return moment(value).format(DateFormat);\r\n    }\r\n\r\n    handleDeleteClick = () => {\r\n        this.props.onShowDeleteModal(this.props.eoq);\r\n    };\r\n\r\n    renderCellAction = () => {\r\n        const currentYear = new Date().getFullYear();\r\n        const eoq = this.props.eoq;\r\n\r\n        if (eoq.year + 1 >= currentYear && this.props.isHost) {\r\n            return (\r\n                <Fragment>\r\n                    <a className=\"fa fa-pencil-square-o\" title=\"Edit\"\r\n                        href={resolveClientUrl('EOQ/Edit/' + eoq.eoqyId)}\r\n                    />\r\n                    {\r\n                        eoq.statusId === 0 &&\r\n                        <a className=\"fa fa-trash-o remove\" title=\"Delete\" onClick={this.handleDeleteClick} />\r\n                    }\r\n                </Fragment>\r\n            );\r\n        }\r\n\r\n        return (\r\n            <a className=\"fa fa-search\" title=\"Details\"\r\n                href={resolveClientUrl('EOQ/Details/' + eoq.eoqyId)}\r\n            />\r\n        );\r\n    };\r\n\r\n    render() {\r\n        const eoq = this.props.eoq;\r\n        const statusIndex = nominationSettingStatuses.findIndex(x => x.value === eoq.statusId);\r\n\r\n        return (\r\n            <tr>\r\n                <td className=\"text-center\">{this.props.rowIndex}</td>\r\n                <td className=\"text-center\">{eoq.quarter}</td>\r\n                <td className=\"text-center\">{eoq.year}</td>\r\n                <td className=\"text-center\">{this.formatDate(eoq.startDateForNominator)}</td>\r\n                <td className=\"text-center\">{this.formatDate(eoq.endDateForNominator)}</td>\r\n                <td className=\"text-center\">{this.formatDate(eoq.remindDateForNominator)}</td>\r\n                <td className=\"text-center\">{this.formatDate(eoq.endDateForCommittee)}</td>\r\n                <td className={`text-center ${getCssClassNominationStatus(eoq.statusId)}`}>{nominationSettingStatuses[statusIndex].text}</td>\r\n                <td className=\"text-center\">{this.renderCellAction()}</td>\r\n            </tr>\r\n        );\r\n    }\r\n}\r\n\r\nexport default Row;","import React, { Component } from 'react';\r\nimport { Modal } from 'react-bootstrap';\r\nimport axios from 'axios';\r\nimport { toast } from 'react-toastify';\r\nimport { Formik } from 'formik';\r\nimport { stringify } from 'qs';\r\n\r\nimport { axiosError, resolveClientUrl, axiosCreateResponseWithFormik } from '../../../common-functions';\r\nimport { validateEOQForm } from '../common';\r\nimport getResource from '../../../resourceHelper';\r\nimport { PostRequestHeaders } from '../../../constants';\r\nimport CreateNominationPeriodForm from '../CreateNominationPeriodForm';\r\n\r\nexport default class Create extends Component {\r\n    renderForm = ({\r\n        values,\r\n        errors,\r\n        touched,\r\n        handleChange,\r\n        handleSubmit,\r\n        setFieldValue }) => {\r\n        return (\r\n            <CreateNominationPeriodForm isEOQ\r\n                values={values} errors={errors} touched={touched}\r\n                setFieldValue={setFieldValue}\r\n                onChange={handleChange}\r\n                onSubmit={handleSubmit}\r\n                onClose={this.props.closeModal}\r\n            />\r\n        );\r\n    };\r\n\r\n    handleSubmit = (values, { setErrors }) => {\r\n        const dateFormat = 'YYYY-MM-DD';\r\n        const eoq = stringify({\r\n            __RequestVerificationToken: document.getElementsByName('__RequestVerificationToken')[0].value,\r\n            quarter: values.quarter.value,\r\n            year: values.year.value,\r\n            startDateForNominator: values.startDateForNominator.format(dateFormat),\r\n            endDateForNominator: values.endDateForNominator.format(dateFormat),\r\n            remindDateForNominator: values.remindDateForNominator.format(dateFormat),\r\n            endDateForCommittee: values.endDateForCommittee.format(dateFormat),\r\n            description: values.description\r\n        });\r\n\r\n        axios({\r\n            url: resolveClientUrl('EOQ/Create'),\r\n            method: 'POST',\r\n            data: eoq,\r\n            headers: PostRequestHeaders\r\n        }).then(response => {\r\n            axiosCreateResponseWithFormik(setErrors, toast, response, () => {\r\n                this.props.closeModal();\r\n                this.props.handleFilterSubmit();\r\n            });\r\n        }).catch(axiosError);\r\n    };\r\n\r\n    render() {\r\n        const currentYear = new Date().getFullYear();\r\n        const eoq = {\r\n            quarter: { value: 1, label: '1st' },\r\n            year: { value: currentYear, label: currentYear },\r\n            startDateForNominator: null,\r\n            endDateForNominator: null,\r\n            remindDateForNominator: null,\r\n            endDateForCommittee: null,\r\n            description: ''\r\n        };\r\n\r\n        return (\r\n            <Modal keyboard={false} backdrop=\"static\"\r\n                show={this.props.showModal} onHide={this.props.closeModal}\r\n                dialogClassName=\"custom-modal modal-md\"\r\n            >\r\n                <Modal.Header closeButton>\r\n                    <Modal.Title>{getResource('AddNominationPeriod')}</Modal.Title>\r\n                </Modal.Header>\r\n                <Formik\r\n                    initialValues={eoq}\r\n                    validate={validateEOQForm}\r\n                    onSubmit={this.handleSubmit}\r\n                    render={this.renderForm}\r\n                />\r\n            </Modal>\r\n        );\r\n    }\r\n}","import React, { Component, Fragment } from 'react';\r\nimport axios from 'axios';\r\n\r\nimport { axiosError, resolveClientUrl } from '../../../common-functions';\r\nimport Filter from './Filter';\r\nimport Table from './Table';\r\n\r\nexport default class EOY extends Component {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            statusId: 1,\r\n            eoys: []\r\n        };\r\n\r\n        this.isHost = document.getElementById('IsHost').checked;\r\n    }\r\n\r\n    componentDidMount() {\r\n        this.getAllEOY();\r\n    }\r\n\r\n    getAllEOY = () => {\r\n        axios.get(resolveClientUrl(`EOY/GetAll?statusId=${this.state.statusId}`))\r\n            .then(response => {\r\n                const data = response.data;\r\n\r\n                this.setState({ eoys: data });\r\n            }).catch(axiosError);\r\n    };\r\n\r\n    handleStatusChange = statusId => {\r\n        this.setState({ statusId });\r\n    };\r\n\r\n    handleSubmit = () => {\r\n        this.getAllEOY();\r\n    };\r\n\r\n    render() {\r\n        return (\r\n            <Fragment>\r\n                <Filter statusId={this.state.statusId}\r\n                    handleStatusChange={this.handleStatusChange}\r\n                    handleFilterSubmit={this.handleSubmit}\r\n                />\r\n\r\n                <Table\r\n                    eoys={this.state.eoys}\r\n                    isHost={this.isHost}\r\n                    handleFilterSubmit={this.handleSubmit}\r\n                />\r\n            </Fragment>\r\n        );\r\n    }\r\n}","import React, { Component } from 'react';\r\nimport { Form, ControlLabel, FormGroup } from 'react-bootstrap';\r\nimport Select from 'react-select';\r\n\r\nimport { statusOptions } from '../common';\r\nimport getResource from '../../../resourceHelper';\r\n\r\nclass Filter extends Component {\r\n    handleStatusChange = selectedOption => {\r\n        this.props.handleStatusChange(selectedOption.value);\r\n    };\r\n\r\n    handleFilterSubmit = event => {\r\n        event.preventDefault();\r\n        this.props.handleFilterSubmit();\r\n    };\r\n\r\n    render() {\r\n        const statusSelected = statusOptions.find(option => option.value === this.props.statusId.toString());\r\n\r\n        return (\r\n            <Form inline className=\"form-filter\" onSubmit={this.handleFilterSubmit}>\r\n                <FormGroup>\r\n                    <ControlLabel>{getResource('Status')}</ControlLabel>\r\n                    <div className=\"control-content\">\r\n                        <Select name=\"StatusId\"\r\n                            isSearchable={false}\r\n                            isClearable={false}\r\n                            options={statusOptions}\r\n                            onChange={this.handleStatusChange}\r\n                            className=\"react-select-container\" classNamePrefix=\"react-select\"\r\n                            value={statusSelected}\r\n                        />\r\n                    </div>\r\n                </FormGroup>\r\n                <FormGroup>\r\n                    <button className=\"btn btn-primary\">{getResource('Search')}</button>\r\n                </FormGroup>\r\n            </Form>\r\n        );\r\n    }\r\n}\r\n\r\nexport default Filter;","import React, { Component, Fragment } from 'react';\r\nimport axios from 'axios';\r\nimport { toast } from 'react-toastify';\r\nimport { stringify } from 'qs';\r\n\r\nimport { axiosError, resolveClientUrl } from '../../../common-functions';\r\nimport { PostRequestHeaders } from '../../../constants';\r\nimport getResource from '../../../resourceHelper';\r\nimport ConfirmationModal from '../../../shared/components/ConfirmationModal';\r\nimport Row from './Row';\r\nimport CreateEOY from './Create';\r\n\r\nclass Table extends Component {\r\n    constructor(props) {\r\n        super(props);\r\n\r\n        this.state = {\r\n            showCreateModal: false,\r\n            showDeleteModal: false,\r\n            eoySelected: null\r\n        };\r\n    }\r\n\r\n    handleShowCreateEoYModal = () => this.setState({ showCreateModal: true });\r\n\r\n    handleCloseCreateModal = () => this.setState({ showCreateModal: false });\r\n\r\n    handleShowDeleteModal = eoySelected => {\r\n        this.setState({\r\n            showDeleteModal: true,\r\n            eoySelected: eoySelected\r\n        });\r\n    };\r\n\r\n    handleCloseDeleteModal = () => {\r\n        this.setState({\r\n            showDeleteModal: false,\r\n            eoySelected: null\r\n        });\r\n    };\r\n\r\n    handleDeleteEOY = () => {\r\n        axios({\r\n            url: resolveClientUrl('NominationPeriod/Delete'),\r\n            method: 'DELETE',\r\n            data: stringify({\r\n                __RequestVerificationToken: document.getElementsByName('__RequestVerificationToken')[0].value,\r\n                id: this.state.eoySelected.eoqyId\r\n            }),\r\n            headers: PostRequestHeaders\r\n        }).then(response => {\r\n            const data = response.data;\r\n\r\n            if (data.isSuccessful) {\r\n                toast.success(getResource('DeletedSuccessfully'));\r\n\r\n                this.closeDeleteModal();\r\n                this.props.handleFilterSubmit();\r\n            } else {\r\n                toast.error(data.message);\r\n            }\r\n        }).catch(axiosError);\r\n    };\r\n\r\n    renderEoYTableHeader = () => {\r\n        return (\r\n            <tr>\r\n                <th>{getResource('SymbolCount')}</th>\r\n                <th>{getResource('Year')}</th>\r\n                <th>{getResource('StartDateForNominator')}</th>\r\n                <th>{getResource('EndDateForNominator')}</th>\r\n                <th>{getResource('RemindDateForNominator')}</th>\r\n                <th>{getResource('EndDateForCommittee')}</th>\r\n                <th>{getResource('Status')}</th>\r\n                <th>{getResource('Action')}</th>\r\n            </tr>\r\n        );\r\n    };\r\n\r\n    render() {\r\n        const { isHost, eoys } = this.props;\r\n\r\n        return (\r\n            <Fragment>\r\n                {\r\n                    isHost &&\r\n                    < div className=\"add-nomination-period\">\r\n                        <a className=\"pull-left btn btn-primary\" onClick={this.handleShowCreateEoYModal}>\r\n                            {getResource('AddNominationPeriod')}\r\n                        </a>\r\n                    </div>\r\n                }\r\n                <div className=\"table-nomination-period\">\r\n                    <table className=\"table table-bordered\">\r\n                        <thead>\r\n                            {\r\n                                this.renderEoYTableHeader()\r\n                            }\r\n                        </thead>\r\n                        <tbody>\r\n                            {\r\n                                eoys.length === 0 &&\r\n                                <tr>\r\n                                    <td className=\"empty-result\" colSpan=\"9\">{getResource('NoRecordFound')}</td>\r\n                                </tr>\r\n                            }\r\n                            {\r\n                                eoys.length > 0 &&\r\n                                eoys.map((eoy, index) => {\r\n                                    return (\r\n                                        <Row key={'eoy-' + eoy.eoqyId}\r\n                                            rowIndex={index + 1}\r\n                                            eoy={eoy}\r\n                                            isHost={isHost}\r\n                                            onShowDeleteModal={this.handleShowDeleteModal}\r\n                                        />\r\n                                    );\r\n                                })\r\n                            }\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n\r\n                {\r\n                    this.state.showCreateModal &&\r\n                    <CreateEOY\r\n                        showModal={this.state.showCreateModal}\r\n                        closeModal={this.handleCloseCreateModal}\r\n                        handleFilterSubmit={this.props.handleFilterSubmit}\r\n                    />\r\n                }\r\n                {\r\n                    this.state.showDeleteModal &&\r\n                    <ConfirmationModal\r\n                        action=\"delete\"\r\n                        name={this.state.eoySelected.title}\r\n                        showModal={this.state.showDeleteModal}\r\n                        onCloseModal={this.handleCloseDeleteModal}\r\n                        onSubmit={this.handleDeleteEOY}\r\n                    />\r\n                }\r\n            </Fragment>\r\n        );\r\n    }\r\n}\r\n\r\nexport default Table;","import React, { Component, Fragment } from 'react';\r\nimport moment from 'moment';\r\n\r\nimport { resolveClientUrl } from '../../../common-functions';\r\nimport { DateFormat } from '../../../constants';\r\nimport { getCssClassNominationStatus, nominationSettingStatuses } from '../common';\r\n\r\nclass Row extends Component {\r\n    formatDate(value) {\r\n        return moment(value).format(DateFormat);\r\n    }\r\n\r\n    handleDeleteClick = () => {\r\n        this.props.onShowDeleteModal(this.props.eoy);\r\n    };\r\n\r\n    renderCellAction = () => {\r\n        const currentYear = new Date().getFullYear();\r\n        const eoy = this.props.eoy;\r\n\r\n        if (eoy.year + 1 >= currentYear && this.props.isHost) {\r\n            return (\r\n                <Fragment>\r\n                    <a className=\"fa fa-pencil-square-o\" title=\"Edit\"\r\n                        href={resolveClientUrl('EOY/Edit/' + eoy.eoqyId)}\r\n                    />\r\n                    {\r\n                        eoy.statusId === 0 &&\r\n                        <a className=\"fa fa-trash-o remove\" title=\"Delete\" onClick={this.handleDeleteClick} />\r\n                    }\r\n                </Fragment>\r\n            );\r\n        }\r\n\r\n        return (\r\n            <a className=\"fa fa-search\" title=\"Details\"\r\n                href={resolveClientUrl('EOY/Details/' + eoy.eoqyId)}\r\n            />\r\n        );\r\n    };\r\n\r\n    render() {\r\n        const eoy = this.props.eoy;\r\n        const statusIndex = nominationSettingStatuses.findIndex(x => x.value === eoy.statusId);\r\n\r\n        return (\r\n            <tr>\r\n                <td className=\"text-center\">{this.props.rowIndex}</td>\r\n                <td className=\"text-center\">{eoy.year}</td>\r\n                <td className=\"text-center\">{this.formatDate(eoy.startDateForNominator)}</td>\r\n                <td className=\"text-center\">{this.formatDate(eoy.endDateForNominator)}</td>\r\n                <td className=\"text-center\">{this.formatDate(eoy.remindDateForNominator)}</td>\r\n                <td className=\"text-center\">{this.formatDate(eoy.endDateForCommittee)}</td>\r\n                <td className={`text-center ${getCssClassNominationStatus(eoy.statusId)}`}>{nominationSettingStatuses[statusIndex].text}</td>\r\n                <td className=\"text-center\">{this.renderCellAction()}</td>\r\n            </tr>\r\n        );\r\n    }\r\n}\r\n\r\nexport default Row;","import React, { Component } from 'react';\r\nimport { Modal } from 'react-bootstrap';\r\nimport axios from 'axios';\r\nimport { toast } from 'react-toastify';\r\nimport { Formik } from 'formik';\r\nimport { stringify } from 'qs';\r\n\r\nimport { axiosError, resolveClientUrl, axiosCreateResponseWithFormik } from '../../../common-functions';\r\nimport { validateEOYForm } from '../common';\r\nimport getResource from '../../../resourceHelper';\r\nimport { PostRequestHeaders } from '../../../constants';\r\nimport CreateNominationPeriodForm from '../CreateNominationPeriodForm';\r\n\r\nclass Create extends Component {\r\n    handleSubmit = (values, { setErrors }) => {\r\n        const dateFormat = 'YYYY-MM-DD';\r\n        const eoy = stringify({\r\n            __RequestVerificationToken: document.getElementsByName('__RequestVerificationToken')[0].value,\r\n            year: values.year.value,\r\n            startDateForNominator: values.startDateForNominator.format(dateFormat),\r\n            endDateForNominator: values.endDateForNominator.format(dateFormat),\r\n            remindDateForNominator: values.remindDateForNominator.format(dateFormat),\r\n            endDateForCommittee: values.endDateForCommittee.format(dateFormat),\r\n            description: values.description\r\n        });\r\n\r\n        axios({\r\n            url: resolveClientUrl('EOY/Create'),\r\n            method: 'POST',\r\n            data: eoy,\r\n            headers: PostRequestHeaders\r\n        }).then(response => {\r\n            axiosCreateResponseWithFormik(setErrors, toast, response, () => {\r\n                this.props.closeModal();\r\n                this.props.handleFilterSubmit();\r\n            });\r\n        }).catch(axiosError);\r\n    };\r\n\r\n    renderForm = ({\r\n        values,\r\n        errors,\r\n        touched,\r\n        handleChange,\r\n        handleSubmit,\r\n        setFieldValue }) => {\r\n        return (\r\n            <CreateNominationPeriodForm isEOQ={false}\r\n                values={values} errors={errors} touched={touched}\r\n                setFieldValue={setFieldValue}\r\n                onChange={handleChange}\r\n                onSubmit={handleSubmit}\r\n                onClose={this.props.closeModal}\r\n            />\r\n        );\r\n    };\r\n\r\n    render() {\r\n        const currentYear = new Date().getFullYear();\r\n        const eoy = {\r\n            year: { value: currentYear, label: currentYear },\r\n            remindDateForNominator: null,\r\n            endDateForCommittee: null,\r\n            startDateForNominator: null,\r\n            endDateForNominator: null,\r\n            description: ''\r\n        };\r\n\r\n        return (\r\n            <Modal id=\"eoy-create-modal\" keyboard={false} backdrop=\"static\"\r\n                show={this.props.showModal}\r\n                onHide={this.props.closeModal}\r\n                dialogClassName=\"custom-modal modal-md\"\r\n            >\r\n                <Modal.Header closeButton>\r\n                    <Modal.Title>{getResource('AddNominationPeriod')}</Modal.Title>\r\n                </Modal.Header>\r\n                <Formik\r\n                    initialValues={eoy}\r\n                    validate={validateEOYForm}\r\n                    onSubmit={this.handleSubmit}\r\n                    render={this.renderForm}\r\n                />\r\n            </Modal>\r\n        );\r\n    }\r\n}\r\n\r\nexport default Create;"],"sourceRoot":""}
